"use strict";(self.webpackChunkstage_human_docs=self.webpackChunkstage_human_docs||[]).push([[8758],{8743(e,n,t){t.r(n),t.d(n,{assets:()=>c,contentTitle:()=>s,default:()=>h,frontMatter:()=>o,metadata:()=>a,toc:()=>d});const a=JSON.parse('{"id":"docs/adr/separate-visual-subjects-review-scenarios-and-staging","title":"0012: Separate Visual Subjects, Review Scenarios, And Staging","description":"Status: Historical terminology; canonical-identity and question-separation","source":"@site/../docs/adr/0012-separate-visual-subjects-review-scenarios-and-staging.md","sourceDirName":"docs/adr","slug":"/docs/adr/separate-visual-subjects-review-scenarios-and-staging","permalink":"/handbook/docs/adr/separate-visual-subjects-review-scenarios-and-staging","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":1785614873000,"sidebarPosition":12,"frontMatter":{}}');var i=t(4848),r=t(8453);const o={},s="0012: Separate Visual Subjects, Review Scenarios, And Staging",c={},d=[{value:"Context",id:"context",level:2},{value:"Decision",id:"decision",level:2},{value:"Consequences",id:"consequences",level:2},{value:"Dogfood Result",id:"dogfood-result",level:2}];function l(e){const n={a:"a",code:"code",h1:"h1",h2:"h2",header:"header",li:"li",ol:"ol",p:"p",strong:"strong",ul:"ul",...(0,r.R)(),...e.components};return(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)(n.header,{children:(0,i.jsx)(n.h1,{id:"0012-separate-visual-subjects-review-scenarios-and-staging",children:"0012: Separate Visual Subjects, Review Scenarios, And Staging"})}),"\n",(0,i.jsx)(n.p,{children:"Status: Historical terminology; canonical-identity and question-separation\nprinciples retained; dedicated Scenario architecture superseded by ADR 0027"}),"\n",(0,i.jsxs)(n.p,{children:["Detached-export terminology and consequences are superseded by\n",(0,i.jsx)(n.a,{href:"/handbook/docs/adr/retire-detached-visual-evidence-pipeline",children:"ADR 0025"}),".\n",(0,i.jsx)(n.a,{href:"/handbook/docs/adr/demote-visual-almanac-to-optional-product-recipe",children:"ADR 0027"})," removes\nVisual Review Scenario as required STAGE vocabulary. Projects may preserve a\nreproducible setup in their own language when recurring utility earns it."]}),"\n",(0,i.jsx)(n.h2,{id:"context",children:"Context"}),"\n",(0,i.jsx)(n.p,{children:"The first Visual Rehearsal implementation optimized for portable captures and\ncontact sheets. That produced technically valid evidence while forcing ordinary\nvisual iteration outside the engine. Replacing that workflow with a native\nVisual Almanac corrected the review surface, but a flatter problem remained:\nan Almanac can list real assets, cameras, lighting modes, and animation controls\nwithout explaining what a reviewer is meant to judge."}),"\n",(0,i.jsx)(n.p,{children:"Lanternworks exposed this gap directly. Its first native Almanac resolved real\nBorough content, staged it through the actual presentation path, provided\ndeterministic states, and exposed camera and lighting controls. Its entries were\nnevertheless organized primarily as subjects. Most static entries showed one\ngeneric authored state, while the useful First Light entry succeeded because it\nimplicitly formed a coherent sequence with meaningful progression. The\nimplementation had the mechanics of review, but not an explicit review\nquestion."}),"\n",(0,i.jsx)(n.p,{children:"A content catalog and a review workflow therefore have different jobs. The\ncatalog answers what content exists. Review needs to answer why a particular\nstate, view, or motion should be inspected. Mirroring the complete catalog into\nSTAGE would recreate Catalog Shadowing; multiplying generic angles would\nrecreate Matrix Without A Question."}),"\n",(0,i.jsx)(n.h2,{id:"decision",children:"Decision"}),"\n",(0,i.jsx)(n.p,{children:"Model native visual review with four distinct concepts:"}),"\n",(0,i.jsxs)(n.ol,{children:["\n",(0,i.jsxs)(n.li,{children:["A ",(0,i.jsx)(n.strong,{children:"Visual Subject"})," is the stable project-owned identity of real game\ncontent. It is resolved from the project's authoritative catalog, prefab,\nscene, definition, generator input, or runtime registry."]}),"\n",(0,i.jsxs)(n.li,{children:["A ",(0,i.jsx)(n.strong,{children:"Visual Review Scenario"})," is a human-authored question applied to one\nsubject or a coherent group. It selects only the states, beats, contexts,\nand truth modes needed to answer that question."]}),"\n",(0,i.jsxs)(n.li,{children:["A ",(0,i.jsx)(n.strong,{children:"Presentation Profile"})," is human-owned staging intent: camera, distance,\nbackground, lighting, rendering, timing, fixtures, seeds, and related\ninspection settings. Profiles may be shared between scenarios and remain\neditable through ordinary project authoring surfaces."]}),"\n",(0,i.jsxs)(n.li,{children:["A ",(0,i.jsx)(n.strong,{children:"Native Stage"})," is the engine-owned scene, editor tool, runtime gallery,\nor composed game route that resolves and presents the real subject under the\nselected scenario and profile."]}),"\n"]}),"\n",(0,i.jsxs)(n.p,{children:["A ",(0,i.jsx)(n.strong,{children:"Review Beat"})," is a named state or temporal coordinate within a scenario,\nsuch as anticipation, impact, recovery, loop seam, selected, damaged, dense,\nor error. A beat exists because it contributes to the scenario's question; it\nis not anonymous timestamp coverage."]}),"\n",(0,i.jsx)(n.p,{children:"The Visual Almanac should browse or derive Visual Review Scenarios for\ndeveloper review. A player-facing content browser may separately derive one\nentry per discovered or intentionally visible canonical Subject. That browser\nis a legitimate product feature, not merely a convenience, but generic Subject\npreview is not evidence that a review question was answered. The two catalogs\nreuse canonical identity, resolution, rendering, staging, camera, and\nlifecycle while retaining different purposes and cardinality. One Visual\nSubject may have multiple Scenarios, and one Scenario may compose multiple\nSubjects."}),"\n",(0,i.jsx)(n.p,{children:"Scenario definitions remain sparse and project-owned. A persistent route's\nordinary project map points to their source and lifecycle but does not copy the\nproject's subject inventory or Scenario records. Generated defaults may\npropose a Scenario, but they may not overwrite a human-authored question or\nPresentation Profile."}),"\n",(0,i.jsx)(n.p,{children:"State provenance should identify the active scenario, resolved subject IDs,\nReview Beat, truth mode, Presentation Profile, readiness, and relevant effective\nsettings when the project can report them credibly. Visual observation remains\nindependent of that report. Optional Evidence Export preserves the same native\ncoordinates rather than inventing a second shot grammar."}),"\n",(0,i.jsx)(n.p,{children:"Earlier declaration versions attempted to expose the project-owned Review\nScenario source, human question authority, and named-beat capability without\ncopying Scenario records. ADR 0026 retired that duplicate manifest. The same\nboundary remains current through the ordinary project map and project-owned\nauthoring sources."}),"\n",(0,i.jsx)(n.h2,{id:"consequences",children:"Consequences"}),"\n",(0,i.jsxs)(n.ul,{children:["\n",(0,i.jsx)(n.li,{children:"A reviewer can understand the intended judgment before moving the camera or\nplaying motion."}),"\n",(0,i.jsx)(n.li,{children:"The developer Scenario catalog grows by useful questions rather than by\nasset count; a player content browser may grow with canonical game content."}),"\n",(0,i.jsx)(n.li,{children:"Real project catalogs remain authoritative and are not mirrored into STAGE."}),"\n",(0,i.jsx)(n.li,{children:"Human camera and lighting decisions remain durable project data rather than\ngenerated capture defaults."}),"\n",(0,i.jsx)(n.li,{children:"Static previews must earn their place through a meaningful question, not a\nsingle generic angle."}),"\n",(0,i.jsx)(n.li,{children:"Agent control, state provenance, and visual observation can refer to the same\nscenario coordinate without implying human acceptance."}),"\n",(0,i.jsx)(n.li,{children:"The distinction can be dogfooded in engine code before another public schema\nis frozen."}),"\n"]}),"\n",(0,i.jsx)(n.h2,{id:"dogfood-result",children:"Dogfood Result"}),"\n",(0,i.jsx)(n.p,{children:"Lanternworks replaced the generic subject browser with two authored Scenarios:\none asks whether every Structure remains distinguishable at gameplay distance\nunder three lighting contexts; the other asks whether the progression from an\nempty Borough to First Light communicates clearly. The first uses one lineup\nbeat containing all five canonical Structure Subjects. The second uses five\nprogression beats. Both run through the existing native stage and one\nhuman-owned Presentation Profile."}),"\n",(0,i.jsx)(n.p,{children:"That change made the boundary operational without adding a detached scenario\nschema. It also exposed two lifecycle requirements that generic startup checks\nhad hidden: readiness must prove the selected Review Beat is rendered, and\nteardown must tolerate Unity scene-destruction order without redrawing through\na destroyed view. The dogfood therefore supports the decision that a useful\nscenario is a question plus truthful native staging, not a renamed catalog\nentry."}),"\n",(0,i.jsxs)(n.p,{children:["A follow-up product dogfood restored catalog-sized Subject browsing for the\nplayer without inflating developer review. The player can inspect every\ncanonical Structure and its field notes, while developer mode still exposes\nexactly the same two question-driven Scenarios. Both paths use the same\nresolver, deterministic ",(0,i.jsx)(n.code,{children:"BoroughSession"}),", ",(0,i.jsx)(n.code,{children:"BoroughWorldView"}),", camera, and\nteardown. The correction also made controller operation explicit: opening\nestablishes focus, Submit activates the focused entry, Cancel closes, and the\nHUD focus is restored. Lanternworks has no canonical production animation, so\nthe dogfood deliberately added no fake motion merely to generate a video."]})]})}function h(e={}){const{wrapper:n}={...(0,r.R)(),...e.components};return n?(0,i.jsx)(n,{...e,children:(0,i.jsx)(l,{...e})}):l(e)}},8453(e,n,t){t.d(n,{R:()=>o,x:()=>s});var a=t(6540);const i={},r=a.createContext(i);function o(e){const n=a.useContext(r);return a.useMemo(function(){return"function"==typeof e?e(n):{...n,...e}},[n,e])}function s(e){let n;return n=e.disableParentContext?"function"==typeof e.components?e.components(i):e.components||i:o(e.components),a.createElement(r.Provider,{value:n},e.children)}}}]);